GrainHopperSlideGateMaker.ironStock=14; GrainHopperSlideGateMaker.bronzeStock=12; GrainHopperSlideGateMaker.woodStock=12; GrainHopperSlideGateMaker.leatherStock=8; GrainHopperSlideGateMaker.silverStock=8; GrainHopperSlideGateMaker.goldStock=6; GrainHopperSlideGateMaker.jewelStock=4; GrainHopperSlideGateMaker.pearlStock=4
