function GrainHopperSlideGateMaker.init() GrainHopperSlideGateMaker.ironStock=14; GrainHopperSlideGateMaker.bronzeStock=12; GrainHopperSlideGateMaker.woodStock=12; GrainHopperSlideGateMaker.leatherStock=8; GrainHopperSlideGateMaker.silverStock=8; GrainHopperSlideGateMaker.goldStock=6; GrainHopperSlideGateMaker.jewelStock=4; GrainHopperSlideGateMaker.pearlStock=4; GrainHopperSlideGateMaker.productStock={}; GrainHopperSlideGateMaker.buildings={}; GrainHopperSlideGateMaker.maker=nil; GrainHopperSlideGateMaker.activeMaking={}; GrainHopperSlideGateMaker.totalProducts=0; GrainHopperSlideGateMaker.dayTimer=0; print("[GrainHopperSlideGateMaker] Royal Grain Hopper Slide Gate Maker System initialized (6 products, 4 buildings)") end
function GrainHopperSlideGateMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GrainHopperSlideGateMaker.maker={name=n or ("Drsnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Drsnik najet: %s (spretnost: %d)",GrainHopperSlideGateMaker.maker.name,s),"success") end; return true end
function GrainHopperSlideGateMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GrainHopperSlideGateMaker.build(id) local ok,e=GrainHopperSlideGateMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GrainHopperSlideGateMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GrainHopperSlideGateMaker.getQualityBonus() local b=0; for _,bd in ipairs(GrainHopperSlideGateMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GrainHopperSlideGateMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GrainHopperSlideGateMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GrainHopperSlideGateMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GrainHopperSlideGateMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GrainHopperSlideGateMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GrainHopperSlideGateMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GrainHopperSlideGateMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GrainHopperSlideGateMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GrainHopperSlideGateMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GrainHopperSlideGateMaker.buildings==0 then return false,"Potrebna drsna delavnica" end; if not GrainHopperSlideGateMaker.maker then return false,"Potreben drsnik" end; return true end
function GrainHopperSlideGateMaker.make(pt,qty) qty=qty or 1; local ok,e=GrainHopperSlideGateMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GrainHopperSlideGateMaker.ironStock=GrainHopperSlideGateMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GrainHopperSlideGateMaker.bronzeStock=GrainHopperSlideGateMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GrainHopperSlideGateMaker.woodStock=GrainHopperSlideGateMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GrainHopperSlideGateMaker.leatherStock=GrainHopperSlideGateMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GrainHopperSlideGateMaker.silverStock=GrainHopperSlideGateMaker.silverStock-d.silverCost*qty end; if d.goldCost then GrainHopperSlideGateMaker.goldStock=GrainHopperSlideGateMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GrainHopperSlideGateMaker.jewelStock=GrainHopperSlideGateMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GrainHopperSlideGateMaker.pearlStock=GrainHopperSlideGateMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GrainHopperSlideGateMaker.maker then t=math.max(1,t-math.floor(GrainHopperSlideGateMaker.maker.skill/13)) end; table.insert(GrainHopperSlideGateMaker.activeMaking,{id="grainhopperslidegate_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GrainHopperSlideGateMaker.completeMaking(m) local q=1.0+(GrainHopperSlideGateMaker.getQualityBonus()/100); if GrainHopperSlideGateMaker.maker then q=q+(GrainHopperSlideGateMaker.maker.skill/140) end; q=math.min(2.5,q); GrainHopperSlideGateMaker.productStock[m.productType]=(GrainHopperSlideGateMaker.productStock[m.productType] or 0)+m.quantity; GrainHopperSlideGateMaker.totalProducts=GrainHopperSlideGateMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GrainHopperSlideGateMaker.maker then GrainHopperSlideGateMaker.maker.itemsMade=GrainHopperSlideGateMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GrainHopperSlideGateMaker.maker.skill=math.min(100,GrainHopperSlideGateMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Drsnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"grainhopperslidegate.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GrainHopperSlideGateMaker.update(dt) if not _G.state then return end; GrainHopperSlideGateMaker.dayTimer=GrainHopperSlideGateMaker.dayTimer+dt; if GrainHopperSlideGateMaker.dayTimer>=30 then GrainHopperSlideGateMaker.dayTimer=0; for i=#GrainHopperSlideGateMaker.activeMaking,1,-1 do local m=GrainHopperSlideGateMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GrainHopperSlideGateMaker.completeMaking(m); table.remove(GrainHopperSlideGateMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GrainHopperSlideGateMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GrainHopperSlideGateMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GrainHopperSlideGateMaker.getStats() return {ironStock=GrainHopperSlideGateMaker.ironStock,bronzeStock=GrainHopperSlideGateMaker.bronzeStock,woodStock=GrainHopperSlideGateMaker.woodStock,leatherStock=GrainHopperSlideGateMaker.leatherStock,silverStock=GrainHopperSlideGateMaker.silverStock,goldStock=GrainHopperSlideGateMaker.goldStock,jewelStock=GrainHopperSlideGateMaker.jewelStock,pearlStock=GrainHopperSlideGateMaker.pearlStock,productStock=GrainHopperSlideGateMaker.productStock,numBuildings=#GrainHopperSlideGateMaker.buildings,hasMaker=GrainHopperSlideGateMaker.maker~=nil,makerName=GrainHopperSlideGateMaker.maker and GrainHopperSlideGateMaker.maker.name or "—",makerSkill=GrainHopperSlideGateMaker.maker and GrainHopperSlideGateMaker.maker.skill or 0,activeMaking=#GrainHopperSlideGateMaker.activeMaking,totalProducts=GrainHopperSlideGateMaker.totalProducts} end
